/* mais espaço na vertical: plataformas flutuantes, blocos e o que está em cima deles sobem 20% em relação ao chão; o pulo sobe junto (fase a fase) */
function liftLevel(L,k,jk){
  var G=L.solids.filter(function(s){return !(s[3]>.5)&&s[2]<9});
  function g(x,y){var t=-99;G.forEach(function(s){if(x>=s[0]-.05&&x<=s[1]+.05&&s[2]<=y+.01&&s[2]>t)t=s[2]});return t}
  var S=L.sand;function skip(x){return S&&x>S.x0-2&&x<S.x1+2}/* a subida da areia (escada em zigue-zague) fica como está */
  function ly(x,y){var t=g(x,y);if(skip(x)||t<-50||y>=9||y-t<1.6)return y;return t+(y-t)*k}
  function lyF(x0,x1,y){if(skip((x0+x1)/2))return y;var a=g(x0,y),b=g(x1,y),c=g((x0+x1)/2,y),t=Math.max(a,b,c);if(t<-50||y>=9)return y;return t+(y-t)*k}
  (L.floats||[]).forEach(function(f){if(f[2]<9)f[2]=+lyF(f[0],f[1],f[2]).toFixed(2)});
  (L.blocks||[]).forEach(function(b){var t=g(b.x,b.y);if(!skip(b.x)&&t>-50&&b.y<9&&b.y-t>=1.5)b.y=+(t+(b.y-t)*k).toFixed(2)});
  (L.coins||[]).forEach(function(c){if(c[0]==='r')c[3]=+ly((c[1]+c[2])/2,c[3]).toFixed(2);else if(c[0]==='a')c[2]=+ly(c[1],c[2]).toFixed(2)});
  ['gems','hearts'].forEach(function(n){(L[n]||[]).forEach(function(q){q[1]=+ly(q[0],q[1]).toFixed(2)})});
  (L.enemies||[]).forEach(function(e){if(e.t==='bat'||e.t==='wbeetle')e.y=+ly((e.x0+e.x1)/2,e.y).toFixed(2)});
  L.jk=jk;L.liftK=k;
}
