function blockStd(L){var S=(L.solids||[]).filter(function(q){return !(q[3]>.5)}).map(function(q){return [q[0],q[1],q[2]]}).concat((L.floats||[]).map(function(q){return [q[0],q[1],q[2]]})).concat((L.crumbles||[]).map(function(q){return [q[0],q[1],q[2]]}));
  function g(x,y){var t=-99;S.forEach(function(q){if(x>=q[0]-.01&&x<=q[1]+.01&&q[2]<=y-.5&&q[2]>t)t=q[2]});return t}
  var B=(L.blocks||[]).slice().sort(function(a,b){return a.y-b.y||a.x-b.x}),used={};
  B.forEach(function(b,i){if(used[i])return;var row=[b];used[i]=1;var go=true;while(go){go=false;B.forEach(function(c,j){if(used[j]||Math.abs(c.y-b.y)>.01)return;if(row.some(function(r){return Math.abs(r.x-c.x)<=1.05})){row.push(c);used[j]=1;go=true}})}
    var gt=-99;row.forEach(function(r){gt=Math.max(gt,g(r.x,r.y))});if(gt<-50)return;var d=b.y-gt;if(d<1.85||d>2.95)return;var ny=+(gt+2.4).toFixed(2);
    /* teto logo acima (plataforma de cima): o item que sai do bloco precisa de espaço — aí o bloco fica onde estava */
    var cb=99;row.forEach(function(r){(L.solids||[]).concat((L.floats||[]).map(function(f){return [f[0],f[1],f[2],f[2]-.5]})).forEach(function(q){var bot=q[3];if(bot===undefined)return;if(r.x>=q[0]-.01&&r.x<=q[1]+.01&&bot>=r.y+1-.01&&bot<cb)cb=bot})});if(ny+2.05>cb)return;
    row.forEach(function(r){r.y=ny})})}
LEVELS.forEach(function(L,i){if(i===12||i===13)return;blockStd(L);if(L.pre)blockStd(L.pre)});
